#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_variant_resolves() {
        for icon in ALL {
            let path = icon.path();
            assert!(bytes(&path).is_some_and(|b| !b.is_empty()), "{path}");
        }
    }
}
